function heaviestPath(root: TreeNode | null): number {
  const adj = new Map<TreeNode, TreeNode[]>();
  const link = (a: TreeNode, b: TreeNode) => { adj.get(a)!.push(b); adj.get(b)!.push(a); };
  const nodes: TreeNode[] = [root!];
  for (let i = 0; i < nodes.length; i++) adj.set(nodes[i], []), nodes.push(...[nodes[i].left, nodes[i].right].filter((c): c is TreeNode => !!c));
  for (const n of nodes) for (const c of [n.left, n.right]) if (c) link(n, c);
  let best = -Infinity;
  for (const start of nodes) {
    const stack: [TreeNode, TreeNode | null, number][] = [[start, null, start.val]];
    while (stack.length) {
      const [n, from, sum] = stack.pop()!;
      best = Math.max(best, sum);
      for (const m of adj.get(n)!) if (m !== from) stack.push([m, n, sum + m.val]);
    }
  }
  return best;
}

