class Solution:
    def heaviestPath(self, root: Optional[TreeNode]) -> int:
        adj = defaultdict(list)
        nodes = [root]
        for n in nodes:
            for c in (n.left, n.right):
                if c:
                    adj[n].append(c)
                    adj[c].append(n)
                    nodes.append(c)
        best = -math.inf
        for start in nodes:
            stack = [(start, None, start.val)]
            while stack:
                n, came_from, total = stack.pop()
                best = max(best, total)
                for m in adj[n]:
                    if m is not came_from:
                        stack.append((m, n, total + m.val))
        return best

