function heaviestPath(root: TreeNode | null): number {
  let best = -Infinity;
  const gain = (n: TreeNode | null): number => {
    if (!n) return 0;
    const l = Math.max(0, gain(n.left)), r = Math.max(0, gain(n.right)); // drop branches that hurt
    best = Math.max(best, n.val + l + r); // path bending here
    return n.val + Math.max(l, r);        // a parent can extend only one branch
  };
  gain(root);
  return best;
}

